const [engine,baseline,gateway,sidecar,outArg]=process.argv.slice(2);assert(['ts','native'].includes(engine));const out=resolve(outArg);await mkdir(out,{mode:0o700,recursive:false});
const fixed='cc7c4e653b15c8b2cec7bcf2d15d41d69396ae85';assert.equal(execFileSync('git',['-C',baseline,'rev-parse','HEAD'],{encoding:'utf8'}).trim(),fixed);assert.equal(process.versions.node,'22.22.0');assert.equal(process.versions.icu,'78.2');
