const home=join(out,'home'),project=join(out,'project'),tmp=join(out,'tmp');for(const p of [home,project,tmp])await mkdir(p,{mode:0o700});
const key=Buffer.alloc(32,7),encodedKey=key.toString('base64').replace(/=$/,'');const token='mock-callback-token';
await writeFile(join(home,'pilotdeck.yaml'),`schemaVersion: 1\nextension: {builtinPluginsEnabled: {browser-use: false, funasr: false, windows-skills: false}}\nagent: {model: fixture/mock}\nmodel:\n  providers:\n    fixture:\n      protocol: openai\n      url: http://127.0.0.1:1/v1\n      apiKey: mock-only\n      models: {mock: {}}\ntelemetry: {enabled: false}\nadapters:\n  apiServer:\n    enabled: true\n    apiKey: mock-channel-key\n    extra:\n      host: 127.0.0.1\n      port: ${api}\n  wecomCallback:\n    enabled: true\n    token: ${token}\n    extra:\n      corpId: mock-corp\n      agentId: '1000001'\n      secret: mock-only\n      encodingAesKey: ${encodedKey}\n      host: 127.0.0.1\n      port: ${callback}\n`);
await writeFile(join(home,'token'),'http-three-token\n',{mode:0o600});
const args=engine==='ts'?['--import',join(baseline,'node_modules/tsx/dist/loader.mjs'),join(baseline,'src/cli/pilotdeck.ts'),'server']:[gateway,'--native','--home',home,'--project',project,'--listen','127.0.0.1:0','--token-file',join(home,'token'),'--sidecar',sidecar,'--drain-ms','2000'];
const binary=engine==='ts'?process.execPath:args.shift();const env={PATH:process.env.PATH,LANG:'C.UTF-8',HOME:home,PILOT_HOME:home,TMPDIR:tmp,PILOTDECK_GATEWAY_HOST:'127.0.0.1',PILOTDECK_GATEWAY_PORT:String(await port()),PILOTDECK_GATEWAY_TOKEN:'http-three-token',PILOTDECK_GATEWAY_TOKEN_PATH:join(home,'token'),PILOTDECK_SKIP_BROWSER_OPEN:'1',DATABASE_PATH:join(home,'auth.db'),WORKSPACES_ROOT:join(out,'workspaces')};
const child=spawn(binary,args,{env,cwd:project,stdio:['ignore','pipe','pipe']});let stdout='',stderr='';child.stdout.on('data',x=>stdout+=x);child.stderr.on('data',x=>stderr+=x);const exited=new Promise(ok=>child.once('exit',(code,signal)=>ok({code,signal})));const rows=[];let failure=null,exit=null;
async function request(url,init={}){const r=await fetch(url,{...init,signal:AbortSignal.timeout(2000)});const body=await r.text();const row={method:init.method??'GET',path:new URL(url).pathname,status:r.status,body,headers:Object.fromEntries(r.headers)};rows.push(row);return row;}
async function wait(url){const end=Date.now()+30000;for(;;){if(child.exitCode!==null)throw Error('server exited '+child.exitCode);try{await request(url);return;}catch(e){if(Date.now()>end)throw e;await new Promise(r=>setTimeout(r,50));}}}
try{
 await wait(`http://127.0.0.1:${api}/health`);await wait(`http://127.0.0.1:${callback}/wecom/callback`);
 const options=await request(`http://127.0.0.1:${api}/any`,{method:'OPTIONS',headers:{Origin:'http://fixture.local','Access-Control-Request-Method':'POST'}});assert.equal(options.status,204);assert.equal(options.body,'');
 for(const suffix of ['/','/nested/path?x=1']){const row=await request(`http://127.0.0.1:${api}${suffix}`,{method:'OPTIONS',headers:{Origin:'http://fixture.local','Access-Control-Request-Method':'POST'}});assert.equal(row.status,204);assert.equal(row.body,'');}const postModels=await request(`http://127.0.0.1:${api}/v1/models`,{method:'POST',body:''});assert.equal(postModels.status,200);const healthHead=await request(`http://127.0.0.1:${api}/health`,{method:'HEAD'});assert.equal(healthHead.status,200);const missingAPI=await request(`http://127.0.0.1:${api}/missing-route`);assert.equal(missingAPI.status,404);
 const models=await request(`http://127.0.0.1:${api}/v1/models`);assert.equal(models.status,200);const parsed=JSON.parse(models.body);assert.equal(parsed.object,'list');assert(Array.isArray(parsed.data)&&parsed.data.length>0);assert.equal(parsed.data[0].object,'model');assert.equal(parsed.data[0].owned_by,'gateway');
 const echo=Buffer.from('verify-echo-42'),corp=Buffer.from('mock-corp'),length=Buffer.alloc(4);length.writeUInt32BE(echo.length);let plain=Buffer.concat([Buffer.alloc(16,3),length,echo,corp]);const pad=32-plain.length%32;plain=Buffer.concat([plain,Buffer.alloc(pad,pad)]);const cipher=createCipheriv('aes-256-cbc',key,key.subarray(0,16));cipher.setAutoPadding(false);const enc=Buffer.concat([cipher.update(plain),cipher.final()]).toString('base64');const timestamp='1700000000',nonce='mock-nonce';const signature=createHash('sha1').update([token,timestamp,nonce,enc].sort().join('')).digest('hex');
 const query=new URLSearchParams({msg_signature:signature,timestamp,nonce,echostr:enc});const valid=await request(`http://127.0.0.1:${callback}/wecom/callback?${query}`);assert.equal(valid.status,200);assert.equal(valid.body,'verify-echo-42');for(const route of ['/','/nested/callback-alias']){const alternative=await request(`http://127.0.0.1:${callback}${route}?${query}`);assert.equal(alternative.status,200);assert.equal(alternative.body,'verify-echo-42');}const unsupported=await request(`http://127.0.0.1:${callback}/anything`,{method:'PUT',body:''});assert.equal(unsupported.status,405);query.set('msg_signature','bad');const invalid=await request(`http://127.0.0.1:${callback}/wecom/callback?${query}`);assert.equal(invalid.status,403);const missing=await request(`http://127.0.0.1:${callback}/wecom/callback`);assert.equal(missing.status,400);
}catch(e){failure=String(e.stack??e);}finally{
 if(child.exitCode===null)child.kill('SIGTERM');exit=await Promise.race([exited,new Promise(r=>setTimeout(()=>r({code:null,signal:'timeout'}),12000))]);if(exit.signal==='timeout')child.kill('SIGKILL');
 const result={engine,baseline:fixed,sourceManifestSha256:process.env.PDRS_SOURCE_MANIFEST_SHA256, gatewaySha256:await hash(gateway),sidecarSha256:await hash(sidecar),node:process.versions.node,icu:process.versions.icu,scriptSha256:await hash(new URL(import.meta.url)),portReservation:'bind/drop, collision fails',rows,exit,failure,formalAcceptance:false};
 await writeFile(join(out,'result.json'),JSON.stringify(result,null,2)+'\n',{flag:'wx'});await writeFile(join(out,'server.stdout'),stdout,{flag:'wx'});await writeFile(join(out,'server.stderr'),stderr,{flag:'wx'});
}
if(failure||exit.code!==0)process.exitCode=1;
